/** Synthetic full credit: the original invoice and all its amounts stay intact. */
export const completeCreditNote = (): InvoiceWithItems => {
  const source = completeInvoice();
  return {
    ...source,
    id: 'credit-test',
    reference: 'AV-2026-00001',
    document_type: 'credit_note',
    corrects_invoice_id: source.id,
    credit_note_scope: 'full',
    corrected_invoice_reference: source.reference,
    corrected_invoice_issued_at: source.issued_at,
    issued_at: '2026-09-04T14:00:00Z',
    credit_note_reason: 'Annulation complète de la prestation à la demande du client.',
    payment_method: null,
    early_payment_terms: 'Sans objet.',
    late_payment_terms: 'Sans objet.',
    payment_terms: 'Remboursement ou imputation à convenir avec le client.',
    items: source.items.map((line) => ({
      ...line,
      invoice_id: 'credit-test',
      source_invoice_item_id: line.id,
    })),
    totals: { ...source.totals!, invoice_id: 'credit-test' },
  };
};
